output.arguments:
{"code":"def transform(grid):
    h,w=len(grid),len(grid[0])
    rows=[i for i,r in enumerate(grid) if len(set(r))==1]
    cols=[j for j in range(w) if len({grid[i][j] for i in range(h)})==1]
    nr,nc=len(rows)+1,len(cols)+1
    sep=set()
    for i in rows: sep.add(grid[i][0])
    for j in cols: sep.add(grid[0][j])
    # Boundary separator lines act as frame; otherwise the interior/background color is used.
    boundary=any(i in (0,h-1) for i in rows) or any(j in (0,w-1) for j in cols)
    vals=[v for r in grid for v in r]
    if boundary:
        fill=next(iter(sep))
    else:
        fill=next((v for v in vals if v not in sep), vals[0])
    return [[fill]*nc for _ in range(nr)]"}

